//! **Ruling EV: river combs before and after basin routing, measured on the full pipeline**
//! (owner, 2026-11-13: *"Still see some heavy combing:"*; `DELTA_GEOMETRY_RESEARCH.md` section 14).
//!
//! Each world is generated by `generate_terrain` -- the whole pipeline, carving included, as the app runs it
//! (`use_gpu` off by default, so the numbers reproduce on any machine, and on with `BR_GPU=1`, as the owner's world was
//! made; with rough routing on the GPU flow kernel is skipped anyway) -- once per ARM. The rivers measured are the world's OWN network, the one the map draws
//! (`WorldState::channels` and `stream_order` traced by `trace_river_polylines`, as `WorldGen::rivers_now` does);
//! the receiver tree every consumer rebuilds on the final field (`cartalith_civ::fresh_river_channels_with`, with
//! the world's own roughness and fill tilt) is checked for uphill steps. Arms:
//!
//! - `owner` (seed 51203 only): the owner's world as the phone made it, from the World info dump the phone
//!   printed (`tests/fixtures/owner_world_51203_params.txt`, 123 rows): rough routing, the lake balance and the
//!   shared trunks OFF, because an older save had been opened in that session;
//! - `before`: the app's rules as they were before Ruling EV (rough routing on, basin routing off), which is what
//!   a correct New World made until now;
//! - `after`: Ruling EV's rules (rough routing and basin routing on).
//!
//! Worlds: 51203 (the owner's 2026-11-13 world, 2048 x 1024, 40 075 km, river density 2.5, world structure on);
//! the owner world of the earlier river work, 246371 (2048 x 1311, density 1.55); 483920 and 912345 at 1024 x 656,
//! as `river_routing_measurement.rs` and section 13 measured them.
//!
//! Reported per arm, over the traced network (each polyline split at the wrapped seam and densified to one point
//! a cell): the **comb share** (`river_straight::comb_stats`: length running 2-5 cells beside another river within
//! 20 degrees for 12 cells or more), on the whole map, on depression-filled ground only, and -- for 51203 -- inside
//! the window of cells the owner's two screenshots show; the **straight share** (`straight_stats`, stretches of 8
//! cells or more within 0.25 and within 0.5 cells of their chord), its longest stretch, and both again on filled
//! ground and elsewhere; and **plausibility**: channel steps not strictly down the world's own routing surface
//! of the consumers' rebuilt tree (must be 0), dry ends of the drawn network (a traced river ending on land away
//! from water, the map edge or another river), the
//! largest rise of the routing surface above the plain fill level inside a depression (metres at the world's
//! peak), lake cells by the rain test and under the lake water balance (Ruling ET, whose pools take their inflow
//! from the routed discharge, so routing moves them) and then under Ruling CC's area floor as the map draws them --
//! whole map and, for 51203, inside the owner's window -- ocean cells, river mouths, traced length and rivers. Last, the time to build the routing
//! surface each way on the after world's field (median of five, with min..max; run alone).
//!
//! **Must never** pin a value or change generated output: it only reports. Never un-ignore it: it generates
//! eleven large worlds.
//!
//! ```text
//! cargo test --release -p cartalith-godot --test river_basin_routing_measurement -- --ignored --nocapture --test-threads=1
//! ```
//! `BR_WORLDS=51203,246371,483920,912345` (default all four) picks the worlds; an unknown name panics. `BR_GPU=1` runs
//! the GPU stages. `floor_tilt_against_breadth_on_the_final_field` (same flags) compares the two fill tilts on one field.
#![allow(dead_code)]

#[path = "../src/params.rs"]
mod params;
#[path = "../src/river_straight.rs"]
mod river_straight;

use std::cmp::Reverse;
use std::collections::BinaryHeap;

use cartalith_engine::{WorldParams, generate_terrain};
use river_straight::{comb_stats, straight_stats};

/// The window of cells the owner's 2026-11-13 screenshots show (lane B: centre (165, 256) at zoom 7.88 on a
/// 950 x 834 view), `x0, y0, x1, y1`.
const OWNER_WINDOW: (f64, f64, f64, f64) = (35.0, 50.0, 295.0, 463.0);

/// The owner's 123-row World info dump, applied over `params::defaults()`; panics on a row the registry
/// rejects or clamps, so a stale fixture cannot pass for the owner's world.
fn owner_params() -> WorldParams {
    let text = include_str!("fixtures/owner_world_51203_params.txt");
    let mut p = params::defaults();
    let mut n = 0;
    for line in text.lines() {
        let Some((k, v)) = line.split_once(':') else { continue };
        let (k, v) = (k.trim(), v.trim());
        let val = match v {
            "true" => params::Value::Bool(true),
            "false" => params::Value::Bool(false),
            num => params::Value::Num(num.parse::<f64>().unwrap_or_else(|_| panic!("unparsable {k}: {num}"))),
        };
        assert_eq!(params::set(&mut p, k, val), params::Outcome::Applied, "{k}");
        n += 1;
    }
    assert_eq!(n, 123, "the owner's dump has 123 rows");
    p.gw = 2048;
    p.gh = 1024;
    p.tect.seed = 51203;
    p.map_width_km = 40_075.0;
    p
}

/// `field`'s bits as a heap key that orders like the value (negative heights included).
fn key(v: f32) -> u32 {
    let b = if v.to_bits() == 0x8000_0000 { 0 } else { v.to_bits() };
    if b & 0x8000_0000 != 0 { !b } else { b | 0x8000_0000 }
}

/// The plain Priority-Flood fill level (no tilt), seeded where `build_routing_surface` seeds: every cell below
/// `sea`, the top and bottom rows, and on an unwrapped map the side columns.
fn fill_level(field: &[f32], gw: usize, gh: usize, sea: f64, wrap: bool) -> Vec<f32> {
    let n = gw * gh;
    let mut f = field.to_vec();
    let mut closed = vec![false; n];
    let mut open: BinaryHeap<Reverse<(u32, u32)>> = BinaryHeap::new();
    for i in 0..n {
        let (x, y) = (i % gw, i / gw);
        if (field[i] as f64) < sea || y == 0 || y + 1 == gh || (!wrap && (x == 0 || x + 1 == gw)) {
            closed[i] = true;
            open.push(Reverse((key(f[i]), i as u32)));
        }
    }
    while let Some(Reverse((_, c))) = open.pop() {
        let c = c as usize;
        let (x, y) = ((c % gw) as i64, (c / gw) as i64);
        for dy in -1i64..=1 {
            for dx in -1i64..=1 {
                let (nx, ny) = (x + dx, y + dy);
                if (dx, dy) == (0, 0) || ny < 0 || ny >= gh as i64 || (!wrap && (nx < 0 || nx >= gw as i64)) {
                    continue;
                }
                let j = ny as usize * gw + nx.rem_euclid(gw as i64) as usize;
                if closed[j] {
                    continue;
                }
                closed[j] = true;
                if f[j] < f[c] {
                    f[j] = f[c];
                }
                open.push(Reverse((key(f[j]), j as u32)));
            }
        }
    }
    f
}

/// `q` densified to at most one cell between points, split where it crosses the wrapped seam.
fn pieces(polys: &[Vec<(f64, f64)>]) -> Vec<Vec<(f64, f64)>> {
    let mut out = Vec::new();
    for q in polys {
        let mut cur: Vec<(f64, f64)> = Vec::new();
        for &pt in q {
            if let Some(&l) = cur.last() {
                if (pt.0 - l.0).abs() > 2.5 {
                    if cur.len() > 1 {
                        out.push(std::mem::take(&mut cur));
                    } else {
                        cur.clear();
                    }
                } else {
                    let d = ((pt.0 - l.0).powi(2) + (pt.1 - l.1).powi(2)).sqrt();
                    let k = d.ceil().max(1.0) as usize;
                    for t in 1..k {
                        let f = t as f64 / k as f64;
                        cur.push((l.0 + (pt.0 - l.0) * f, l.1 + (pt.1 - l.1) * f));
                    }
                }
            }
            cur.push(pt);
        }
        if cur.len() > 1 {
            out.push(cur);
        }
    }
    out
}

/// `lines` cut into the pieces whose points satisfy `keep` (a piece ends where a point does not).
fn keep_where(lines: &[Vec<(f64, f64)>], keep: impl Fn((f64, f64)) -> bool) -> Vec<Vec<(f64, f64)>> {
    let mut out = Vec::new();
    for l in lines {
        let mut cur: Vec<(f64, f64)> = Vec::new();
        for &p in l {
            if keep(p) {
                cur.push(p);
            } else if cur.len() > 1 {
                out.push(std::mem::take(&mut cur));
            } else {
                cur.clear();
            }
        }
        if cur.len() > 1 {
            out.push(cur);
        }
    }
    out
}

fn pct(a: f64, b: f64) -> f64 {
    if b > 0.0 { 100.0 * a / b } else { f64::NAN }
}

/// One arm's measurement; prints one block.
fn measure(world: &str, arm: &str, p: &WorldParams) -> (Vec<f32>, f64) {
    let (gw, gh, wrap) = (p.gw, p.gh, p.world);
    let t0 = std::time::Instant::now();
    let ws = generate_terrain(p);
    let gen_s = t0.elapsed().as_secs_f64();
    assert_eq!(ws.basin_routing, p.basin_routing && p.integrate_drainage, "the world records the tilt it was routed with");
    let sea = ws.sea_level;
    let field: &[f32] = &ws.field;
    let rough = cartalith_engine::routing_roughness_of(ws.routing_roughness, gw, gh, wrap);
    let tilt = cartalith_engine::fill_tilt_of(ws.basin_routing);
    // The drawn network: the world's own channels, traced as the map traces them.
    let (Some(order), Some(ch)) = (ws.stream_order.as_ref(), ws.channels.as_ref()) else { panic!("{world}/{arm}: no network") };
    let recv = &ch.recv;
    let polys = cartalith_hydrology::trace_river_polylines(order, recv, gw, gh, 1);
    assert!(!polys.is_empty(), "{world}/{arm}: no traced river");
    // The consumers' rebuild on the final field, for the uphill check.
    let (r_order, r_recv) = cartalith_civ::fresh_river_channels_with(
        field, &ws.flow_discharge, gw, gh, sea, wrap, p.river_density, p.map_width_km, ws.integrated_drainage, rough.as_ref(), tilt,
    );
    let route = cartalith_hydrology::routing_view_with(field, gw, gh, sea, wrap, ws.integrated_drainage, tilt);
    let level = fill_level(field, gw, gh, sea, wrap);
    let filled: Vec<bool> = (0..gw * gh).map(|i| level[i] > field[i]).collect();
    let cell = |q: (f64, f64)| -> usize { (q.1.floor() as i64).clamp(0, gh as i64 - 1) as usize * gw + (q.0.floor() as i64).rem_euclid(gw as i64) as usize };
    let lines = pieces(&polys);
    let on_f = keep_where(&lines, |q| filled[cell(q)]);
    let off_f = keep_where(&lines, |q| !filled[cell(q)]);
    let c_all = comb_stats(lines.iter().map(|v| v.as_slice()));
    let c_f = comb_stats(on_f.iter().map(|v| v.as_slice()));
    let s25 = straight_stats(lines.iter().map(|v| v.as_slice()), 8.0, 0.25);
    let s50 = straight_stats(lines.iter().map(|v| v.as_slice()), 8.0, 0.5);
    let sf = straight_stats(on_f.iter().map(|v| v.as_slice()), 8.0, 0.25);
    let se = straight_stats(off_f.iter().map(|v| v.as_slice()), 8.0, 0.25);
    let wb = cartalith_civ::build_water_bodies(field, gw, gh, sea, wrap, Some(&ws.rainfall));
    let water = |c: usize| (field[c] as f64) < sea || wb.classification[c] != 0;
    // Plausibility.
    let mut uphill_route = 0usize;
    let mut max_rise = 0f64;
    for i in 0..gw * gh {
        if r_order[i] > 0 && r_recv[i] >= 0 && route[r_recv[i] as usize] >= route[i] {
            uphill_route += 1;
        }
        if filled[i] {
            max_rise = max_rise.max(route[i] as f64 - level[i] as f64);
        }
    }
    let near_water = |c: usize| {
        let (x, y) = ((c % gw) as i64, (c / gw) as i64);
        (-1..=1).any(|dy: i64| {
            (-1..=1).any(|dx: i64| {
                let ny = y + dy;
                ny >= 0 && ny < gh as i64 && (wrap || (0..gw as i64).contains(&(x + dx))) && water(ny as usize * gw + (x + dx).rem_euclid(gw as i64) as usize)
            })
        })
    };
    let (mut dry_ends, mut mouths) = (0usize, 0usize);
    for q in &polys {
        let e = cell(*q.last().unwrap());
        let (x, y) = (e % gw, e / gw);
        let edge = y == 0 || y + 1 == gh || (!wrap && (x == 0 || x + 1 == gw));
        let joins = recv[e] >= 0 && order[recv[e] as usize] >= 1;
        if near_water(e) {
            mouths += 1;
        } else if !edge && !joins {
            dry_ends += 1;
        }
    }
    let lake_cells = wb.classification.iter().filter(|&&c| c == 2).count();
    // The lake water balance (Ruling ET) over the same rain-test bodies, as the app applies it when the world's
    // `lake_balance` is on (without Ruling CC's area floor, which the app applies after it): its pools take their
    // inflow from the routed discharge, so the routing decides how much water reaches a basin's floor.
    let mut wbb = cartalith_civ::build_water_bodies(field, gw, gh, sea, wrap, Some(&ws.rainfall));
    let rep = cartalith_civ::lake_balance::apply_lake_balance(&mut wbb, field, &ws.flow_discharge, &ws.temperature, gw, gh, sea, wrap);
    let balanced_lake_cells = wbb.classification.iter().filter(|&&c| c == 2).count();
    // And with Ruling CC's area floor after it, as the app draws them (`render::water_bodies_floored_balanced`
    // applies the floor after the balance; the maar exemption and painted lakes are not in a fresh world's
    // count): the figure the map shows (verifier finding, 2026-11-13: the whole-map count above looked smaller than
    // one lake the app drew in the owner's window).
    let mut wbf = wbb.clone();
    cartalith_civ::apply_lake_area_floor(&mut wbf, field, gw, gh, sea, wrap, cartalith_civ::lake_area_floor_cells(gw, gh));
    let floored_lake_cells = wbf.classification.iter().filter(|&&c| c == 2).count();
    let ocean_cells = wb.classification.iter().filter(|&&c| c == 1).count();
    let filled_land = (0..gw * gh).filter(|&i| filled[i]).count();
    let land = (0..gw * gh).filter(|&i| field[i] as f64 >= sea).count();
    println!("== {world} / {arm}: {gw}x{gh}, density {}, rough {}, basin {}, generated in {gen_s:.0} s", p.river_density, p.rough_routing, ws.basin_routing);
    println!(
        "   comb {:5.1} % of {:.0} cells (longest {:.0}) | on filled ground {:5.1} % of {:.0} | straight {:5.1} % (tol 0.5: {:5.1} %), longest {:.0} | filled {:5.1} % longest {:.0} | elsewhere {:5.1} % longest {:.0}",
        pct(c_all.comb, c_all.total),
        c_all.total,
        c_all.longest,
        pct(c_f.comb, c_f.total),
        c_f.total,
        pct(s25.straight, s25.total),
        pct(s50.straight, s50.total),
        s25.longest,
        pct(sf.straight, sf.total),
        sf.longest,
        pct(se.straight, se.total),
        se.longest
    );
    if world == "51203" {
        let (x0, y0, x1, y1) = OWNER_WINDOW;
        let win = keep_where(&lines, |q| q.0 >= x0 && q.0 <= x1 && q.1 >= y0 && q.1 <= y1);
        let cw = comb_stats(win.iter().map(|v| v.as_slice()));
        let sw = straight_stats(win.iter().map(|v| v.as_slice()), 8.0, 0.25);
        // The window's lake cells under each rule, so the lake the owner's view would show is a number, not a
        // whole-map share (verifier finding, 2026-11-13).
        let in_win = |i: usize| {
            let (x, y) = ((i % gw) as f64, (i / gw) as f64);
            x >= x0 && x <= x1 && y >= y0 && y <= y1
        };
        let win_count = |c: &[u8]| (0..gw * gh).filter(|&i| in_win(i) && c[i] == 2).count();
        println!(
            "   owner window: comb {:5.1} % of {:.0} cells (longest {:.0}), straight {:5.1} % (longest {:.0}) | lake cells: rain test {}, under the balance {}, with the area floor {}",
            pct(cw.comb, cw.total),
            cw.total,
            cw.longest,
            pct(sw.straight, sw.total),
            sw.longest,
            win_count(&wb.classification),
            win_count(&wbb.classification),
            win_count(&wbf.classification)
        );
    }
    println!(
        "   plausibility: uphill_route {uphill_route}, dry_ends {dry_ends}, max rise above the fill {:.3} m | lake cells {lake_cells} (under the balance {balanced_lake_cells}: {} pools, {} dried, {} flooded; with the area floor {floored_lake_cells}), ocean cells {ocean_cells}, filled {filled_land} of {land} land cells | mouths {mouths}, rivers {}, traced {:.0} cells",
        max_rise * p.peak_m,
        rep.pools,
        rep.cells_dried,
        rep.cells_flooded,
        polys.len(),
        s25.total
    );
    (ws.field.to_vec(), sea)
}

/// The routing surface's build time each way on one field (at the world's own sea level): median of five with
/// min..max, in ms.
fn surface_cost(world: &str, field: &[f32], sea: f64, p: &WorldParams) {
    let time = |tilt: cartalith_hydrology::FillTilt| {
        let mut v: Vec<f64> = (0..5)
            .map(|_| {
                let t = std::time::Instant::now();
                let s = cartalith_hydrology::build_routing_surface_with(field, p.gw, p.gh, sea, p.world, tilt);
                std::hint::black_box(&s);
                t.elapsed().as_secs_f64() * 1e3
            })
            .collect();
        v.sort_by(f64::total_cmp);
        (v[2], v[0], v[4])
    };
    let b = time(cartalith_hydrology::FillTilt::Breadth);
    let f = time(cartalith_hydrology::FillTilt::Floor);
    println!("   {world}: routing surface Breadth {:.0} ms ({:.0}..{:.0}), Floor {:.0} ms ({:.0}..{:.0})", b.0, b.1, b.2, f.0, f.1, f.2);
}

/// For every land cell, the seed (a cell below `sea`, or a map edge) its D8 path over `surf` ends at, or
/// `u32::MAX` for a path that ends anywhere else (a pit, which a routing surface must never have).
fn terminal_seed(surf: &[f32], field: &[f32], gw: usize, gh: usize, sea: f64, wrap: bool) -> Vec<u32> {
    let n = gw * gh;
    let recv = cartalith_hydrology::flow_receivers(surf, gw, gh, wrap);
    let seed = |i: usize| {
        let (x, y) = (i % gw, i / gw);
        (field[i] as f64) < sea || y == 0 || y + 1 == gh || (!wrap && (x == 0 || x + 1 == gw))
    };
    let mut out = vec![u32::MAX; n];
    // Ascending routing height: a receiver is strictly lower, so it is always resolved first.
    let mut order: Vec<usize> = (0..n).collect();
    order.sort_by(|&a, &b| surf[a].total_cmp(&surf[b]).then(a.cmp(&b)));
    for &i in &order {
        out[i] = if seed(i) {
            i as u32
        } else if recv[i] >= 0 {
            out[recv[i] as usize]
        } else {
            u32::MAX
        };
    }
    out
}

/// **The Floor tilt against the breadth-first fill on one field** (verifier finding, 2026-11-13: the Floor tilt's
/// larger rise can top a saddle the breadth-first fill leaves alone and capture the basin behind it). Both
/// surfaces are built on the same final field; reported: the cells each one raises that the other leaves at their
/// terrain, the land cells whose D8 path ends at a different seed (sea cell or map edge), the share of those that
/// sit outside every Breadth-raised cell, and the pits (must be 0).
fn floor_against_breadth(world: &str, field: &[f32], sea: f64, p: &WorldParams) {
    let (gw, gh, wrap) = (p.gw, p.gh, p.world);
    let b = cartalith_hydrology::build_routing_surface_with(field, gw, gh, sea, wrap, cartalith_hydrology::FillTilt::Breadth);
    let f = cartalith_hydrology::build_routing_surface_with(field, gw, gh, sea, wrap, cartalith_hydrology::FillTilt::Floor);
    let n = gw * gh;
    let (mut only_f, mut only_b, mut both) = (0usize, 0usize, 0usize);
    for i in 0..n {
        match (f[i] != field[i], b[i] != field[i]) {
            (true, false) => only_f += 1,
            (false, true) => only_b += 1,
            (true, true) => both += 1,
            _ => {}
        }
    }
    let tb = terminal_seed(&b, field, gw, gh, sea, wrap);
    let tf = terminal_seed(&f, field, gw, gh, sea, wrap);
    let land: Vec<usize> = (0..n).filter(|&i| field[i] as f64 >= sea).collect();
    let moved: Vec<usize> = land.iter().copied().filter(|&i| tb[i] != tf[i]).collect();
    let moved_outside = moved.iter().filter(|&&i| b[i] == field[i]).count();
    let pits = land.iter().filter(|&&i| tb[i] == u32::MAX || tf[i] == u32::MAX).count();
    println!(
        "   {world}: raised by Floor only {only_f}, by Breadth only {only_b}, by both {both} | land cells whose path ends at another seed: {} of {} ({:.3} %), {} of them outside every Breadth-raised cell | pits {pits}",
        moved.len(),
        land.len(),
        pct(moved.len() as f64, land.len() as f64),
        moved_outside
    );
}

#[test]
#[ignore = "measurement: generates four large worlds; run in release, alone"]
fn floor_tilt_against_breadth_on_the_final_field() {
    let pick = std::env::var("BR_WORLDS").unwrap_or_else(|_| "51203,246371,483920,912345".into());
    let gpu = std::env::var("BR_GPU").is_ok_and(|v| v == "1");
    for name in pick.split(',') {
        let mut p = match name {
            "51203" => {
                let mut p = owner_params();
                (p.rough_routing, p.lake_balance, p.civ.merge_ways) = (true, true, true);
                p
            }
            "246371" => {
                let mut p = params::defaults();
                (p.gw, p.gh, p.tect.seed, p.map_width_km, p.river_density) = (2048, 1311, 246_371, 40_075.0, 1.55);
                p
            }
            "483920" | "912345" => {
                let mut p = params::defaults();
                (p.gw, p.gh, p.tect.seed, p.map_width_km) = (1024, 656, name.parse().unwrap(), 40_075.0);
                p
            }
            other => panic!("unknown world {other}"),
        };
        p.use_gpu = gpu;
        p.basin_routing = true;
        let ws = generate_terrain(&p);
        floor_against_breadth(name, &ws.field, ws.sea_level, &p);
    }
}

#[test]
#[ignore = "measurement: generates eleven large worlds; run in release, alone"]
fn basin_routing_before_and_after() {
    let pick = std::env::var("BR_WORLDS").unwrap_or_else(|_| "51203,246371,483920,912345".into());
    for name in pick.split(',') {
        let base = match name {
            "51203" => owner_params(),
            "246371" => {
                let mut p = params::defaults();
                (p.gw, p.gh, p.tect.seed, p.map_width_km, p.river_density) = (2048, 1311, 246_371, 40_075.0, 1.55);
                p
            }
            "483920" | "912345" => {
                let mut p = params::defaults();
                (p.gw, p.gh, p.tect.seed, p.map_width_km) = (1024, 656, name.parse().unwrap(), 40_075.0);
                p
            }
            other => panic!("unknown world {other}"),
        };
        let mut base = base;
        // `BR_GPU=1` runs the GPU stages as the owner's world was made (`use_gpu` on; verifier finding, 2026-11-13:
        // the off-only harness measured a slightly different world than the app's). Off by default, so the numbers
        // reproduce on any machine.
        base.use_gpu = std::env::var("BR_GPU").is_ok_and(|v| v == "1");
        if name == "51203" {
            assert!(!base.rough_routing && !base.lake_balance && !base.civ.merge_ways, "premise: the owner's dump has the three switches off");
            let mut owner = base.clone();
            owner.basin_routing = false;
            measure(name, "owner", &owner);
            base.rough_routing = true;
            base.lake_balance = true;
            base.civ.merge_ways = true;
        }
        let mut before = base.clone();
        before.basin_routing = false;
        measure(name, "before", &before);
        let mut after = base.clone();
        after.basin_routing = true;
        let (field, sea) = measure(name, "after", &after);
        surface_cost(name, &field, sea, &after);
    }
}
